def decrypt(key, s):
    c = bytearray(str(s).encode('utf8'))
    n = len(c)
    if n % 2 != 0:
        return ''
    else:
        n = n // 2
        b = bytearray(n)
        j = 0
        for i in range(0, n):
            c1 = c[j]
            c2 = c[j + 1]
            j = j + 2
            c1 = c1 - 65
            c2 = c2 - 65
            b2 = c2 * 16 + c1
            b1 = b2 ^ key
            b[i] = b1
        try:
            return b.decode('utf8', 'ignore')
        except BaseException:
            system_log.error(get_traceback_message())
            return 'failed'
