        with open(user_info_file, 'r', encoding='utf-8') as fp:
            jsont = json.load(fp)
            jsont['pboxpwd'] = decrypt(pwdkey, jsont['pboxpwd'])
            if 'option_pwd' in jsont:
                jsont['option_pwd'] = decrypt(pwdkey, jsont['option_pwd'])
            if 'rzrq_pwd' in jsont:
                jsont['rzrq_pwd'] = decrypt(pwdkey, jsont['rzrq_pwd'])
            if 'future_pwd' in jsont:
                jsont['future_pwd'] = decrypt(pwdkey, jsont['future_pwd'])
            if 'agw_password' in jsont:
                jsont['agw_password'] = decrypt(pwdkey, jsont['agw_password'])
    return jsont
