def reconnect(trade_account, trade_id):
    count = 1
    current_time = datetime.datetime.now()
    reconnect_flag = False
    while True:
        if datetime.datetime.now() - current_time <= datetime.timedelta(minutes=LOGIN_TIMEOUT):
            error_dict, response = trade_account.reconnect({})
            if error_dict['error_no'] == 0:
                reconnect_flag = True
                login_semaphore.release()
            elif get_trade_status(trade_id) == TradeStatus.TRADE_STOP:
                pass
            else:
                strategy_log.error(f"第{count!s}次后端服务登录失败，错误信息为：{error_dict.get('error_info')!s}")
                count += 1
                time.sleep(LOGIN_FREQUENCY)
                continue
        if reconnect_flag is False:
            strategy_log.error('【login】登录失败，交易即将关闭')
            set_trade_stop_status(trade_id)
        return reconnect_flag

